func _snap_up_to_valid_size(val: int) -> int:
	for s in VALID_TILE_SIZES:
		if s >= val:
			return s
	return 128

func _get_canvas_size_for_tool() -> Vector2i:
	if _is_style_method() and reference_tiles.size() > 0:
		var max_w: = 0
		var max_h: = 0
		for img in reference_tiles:
			if img.get_width() > max_w:
				max_w = img.get_width()
			if img.get_height() > max_h:
				max_h = img.get_height()
		return Vector2i(_snap_up_to_valid_size(max_w), _snap_up_to_valid_size(max_h))

if reference_tiles.size() > 0:
	var style_images = []
	for tile in reference_tiles:
		style_images.append({
			"image": {"base64": get_image.image_to_base64(tile)}, 
			"size": {"width": tile.get_width(), "height": tile.get_height()}
		})
	payload["style_images"] = style_images
	payload["style_options"] = {
		"color_palette": find_child("StyleColorPaletteCheckbox").button_pressed, 
		"outline": find_child("StyleOutlineCheckbox").button_pressed, 
		"detail": find_child("StyleDetailCheckbox").button_pressed, 
		"shading": find_child("StyleShadingCheckbox").button_pressed
	}

return payload

func _on_AddReferenceTileButton_pressed() -> void :
	if reference_tiles.size() >= MAX_REFERENCE_TILES:
		ExtensionsApi.dialog.show_error("Maximum %d reference tiles allowed." % MAX_REFERENCE_TILES)
		return
	var current_project = ExtensionsApi.project.current_project
	var new_image = get_image.get_image(current_project.current_frame, Color.TRANSPARENT, ["Inpainting", "Skeleton"])
	if new_image.is_invisible():
		ExtensionsApi.dialog.show_error("Cannot add empty image. Please draw something first.")
		return
	reference_tiles.append(new_image)
	_update_reference_tiles_label()

function generate_animate_with_text_v3.prepare_image(model, create_new_frames)
  local number_of_frames = model.current_json["frame_count"] or 8

  -- Use the animation preparation function
  return prepareForGeneration.prepare_images_animation(model, create_new_frames, number_of_frames + 1,
