function generate_animation_to_animation.generate(model, dlg_type)

if app.activeSprite.width * app.activeSprite.height > 128 * 128 then
    return app.alert("Sprite must be 128x128 or smaller")
end

model.current_json["image_size"]["width"] = app.activeSprite.width
model.current_json["image_size"]["height"] = app.activeSprite.height

local copy_data = createJson.deepcopy(model.current_json)

-- copy_data["inpainting_images"] = {}
copy_data["n_frames"] = model.current_json["n_images"]
copy_data["reference"] = {
    type = "images",
    images = { {} },
    to_index = copy_data["ai_freedom"],
    -- calibration = {
    --     calibration_image = copy_data["south_reference_image"],
    --     depth_row = 0,
    --     depth_column = 0
    -- },
}

if model.current_json["use_reference_image"] then
    if model.current_json["set_reference_image"] ~= nil and model.current_json["set_reference_image"] ~= "" then
        copy_data["extra_frozen_first_frame"] = {
            type = "rgba_bytes",
            base64 = base64.encode(getImage.get_image_bytes(model.current_json["set_reference_image"])),
            width = model.current_json["set_reference_image"].width,
            height = model.current_json["set_reference_image"].height
        }

        if copy_data["image_size"]["width"] ~= copy_data["extra_frozen_first_frame"]["width"] or copy_data["image_size"]["height"] ~= copy_data["extra_frozen_first_frame"]["height"] then
            return app.alert("Reference image size must match canvas size")
        end
        copy_data["set_reference_image"] = nil
    else
        return app.alert("No reference image set")
    end
else
    copy_data["set_reference_image"] = nil
end

if model.current_json["use_init_image"] then
    copy_data["init_images"] = {}
end
copy_data["inpainting_images"] = {}
copy_data["masks"] = {}
for i = 1, model.current_json["n_images"] do
    local image = getImage.get_image(app.activeSprite, app.activeFrame.frameNumber + i - 1, app.activeImage)
    if image:isEmpty() then
        return app.alert("Missing animation image")
    end
    copy_data["inpainting_images"][i] = {
        base64 = base64.encode(getImage.get_image_bytes(image))
    }

    if model.current_json["use_init_image"] then
        copy_data["init_images"][i] = {
            base64 = base64.encode(getImage.get_image_bytes(image))
        }
    end

    copy_data["reference"]["images"][1][i] = {
        base64 = base64.encode(getImage.get_image_bytes(image))
    }
    -- local black_image = Image(4, 4)
    -- for it in black_image:pixels() do
    --     it(app.pixelColor.rgba(0, 0, 0, 255))
    -- end
    -- black_image:resize(app.activeSprite.width, app.activeSprite.height)

    -- copy_data["masks"][i] = {
    --     base64 = base64.encode(getImage.get_image_bytes(black_image))
    -- }
end

func get_payload():
	var current_project = ExtensionsApi.project.current_project
	var payload: Dictionary = {}


	var reference_image = find_child("ReferenceImagePreview").reference_image
	if reference_image == null:
		ExtensionsApi.dialog.show_error("You need to set a reference image first using the 'Set' button.")
		return null
	elif reference_image.is_invisible():
		ExtensionsApi.dialog.show_error("The reference image is fully transparent, please set another one.")
		return null


	var width = reference_image.get_width()
	var height = reference_image.get_height()


	var action_text = find_child("ActionInput").text
	if action_text.strip_edges() == "":
		ExtensionsApi.dialog.show_error("Please enter an action description.")
		return null

	payload["reference_image"] = {}
	payload["reference_image"]["base64"] = get_image.image_to_base64(reference_image)
	payload["reference_image_size"] = {
		"width": width, 
		"height": height
	}

	payload["action"] = action_text
	payload["image_size"] = {
		"width": width, 
		"height": height
	}


	payload["view"] = PixelLabGlobal.translate_view(find_child("ViewSelect").text)
	payload["direction"] = PixelLabGlobal.translate_direction(find_child("DirectionSelect").text)


	var seed_text = find_child("SeedInput").text
	payload["seed"] = int(seed_text) if seed_text != "" else 0


	payload["no_background"] = find_child("NoBackgroundCheckbox").button_pressed


	payload["output_method"] = find_child("OutputMethodSelect").text
	payload["output_format"] = "frames"

	payload["model_name"] = "animate_with_text"

	return payload

func get_tool_data():
	var current_project = ExtensionsApi.project.current_project
	var width = current_project.size.x
	var height = current_project.size.y


	var target_size = max(_get_nearest_valid_size(width), _get_nearest_valid_size(height))
	var num_frames = _get_num_frames(target_size)

	var output_method = find_child("OutputMethodSelect").text.to_lower()
	var tool_data = {
		"image_amount": num_frames, 
		"cels": {}, 
		"output_method": output_method, 
		"tool_name": "Animate with Text (Pro)", 
		"url": "generate-animate-with-text", 
		"image_size": {
			"width": width, 
			"height": height
		}, 
		"documentation": "https://www.pixellab.ai/docs/tools/animate-with-text-pro", 
		"tool": self, 
		"tier_requirement": 1, 
		"main_ui_button_name": "AnimateWithTextNew"
	}
	return tool_data

func validate_payload(payload):

	var reference_image = find_child("ReferenceImagePreview").reference_image
	if reference_image == null:
		ExtensionsApi.dialog.show_error("You need to set a reference image first using the 'Set' button.")
		return false
	elif reference_image.is_invisible():
		ExtensionsApi.dialog.show_error("The reference image is fully transparent, please set another one.")
		return false

	var width = reference_image.get_width()
	var height = reference_image.get_height()
	var area = width * height


	if area > _get_max_area():
		var max_size = 256 if main.tier > 1 else 128
		ExtensionsApi.dialog.show_error("Reference image area too large. Maximum is %dx%d" % [max_size, max_size])
		return false


	if width != height:
		ExtensionsApi.dialog.show_error("Reference image must be square (width must equal height)")
		return false


	var valid_sizes = _get_valid_sizes()
	if not (width in valid_sizes):

		var target_size = _get_nearest_valid_size(width)

		if width > target_size:
			ExtensionsApi.dialog.show_error("Reference image is too large. Maximum size is %dx%d" % [target_size, target_size])
			return false


		var dialog = ConfirmationDialog.new()
		dialog.title = "Pad Image"
		var sizes_str = ", ".join(valid_sizes.map( func(s): return "%dx%d" % [s, s]))
		dialog.dialog_text = "The reference image must be %s pixels.\nYour image is %dx%d.\n\nWould you like to automatically pad the reference image to %dx%d?" % [
			sizes_str, 
			width, height, 
			target_size, target_size
		]
		dialog.confirmed.connect( func():
			var source_width = width
			var source_height = height
			var x_offset = (target_size - source_width) / 2
			var y_offset = (target_size - source_height) / 2


			DrawingAlgos.resize_canvas(target_size, target_size, x_offset, y_offset)


			var padded_image = Image.create(target_size, target_size, false, Image.FORMAT_RGBA8)
			padded_image.blend_rect(
				reference_image, 
				Rect2i(Vector2i.ZERO, Vector2i(source_width, source_height)), 
				Vector2i(x_offset, y_offset)
			)
			find_child("ReferenceImagePreview").reference_image = padded_image
			find_child("ReferenceImagePreview").texture = find_child("ReferenceImagePreview").create_texture(padded_image)

			dialog.queue_free()
		)
		dialog.canceled.connect( func():
			dialog.queue_free()
		)
		ExtensionsApi.dialog.get_dialogs_parent_node().add_child(dialog)
		dialog.popup_centered()
		return false

func _get_max_area() -> int:
	return 128 * 128

func _get_valid_sizes() -> Array:
	return [32, 64, 128]

func _get_nearest_valid_size(size: int) -> int:
	var valid_sizes = _get_valid_sizes()
	for valid_size in valid_sizes:
		if size <= valid_size:
			return valid_size
	return valid_sizes[-1]

func _get_num_frames(size: int) -> int:
	if size <= 64:
		return 16
	else:
		return 4

func check_project_size():
