func _show_resize_confirmation_dialog_(current_w: int, current_h: int, new_w: int, new_h: int) -> void :
	var dialog = resize_dialog_scene.new()
	ExtensionsApi.dialog.get_dialogs_parent_node().add_child(dialog)
	dialog.resize_confirmed.connect(_on_resize_confirmed)
	dialog.new_project_confirmed.connect(_on_resize_new_project_confirmed)
	dialog.canceled.connect(_on_resize_canceled)
	dialog.setup_dialog(current_w, current_h, new_w, new_h)

func _on_resize_confirmed(new_width: int, new_height: int) -> void :
	DrawingAlgos.resize_canvas(new_width, new_height, 0, 0)
	waiting_for_resize_confirmation = false
	generate()

func _on_resize_new_project_confirmed(new_width: int, new_height: int) -> void :
	var new_project = ExtensionsApi.project.new_project([], "untitled", Vector2(new_width, new_height))
	ExtensionsApi.project.current_project = new_project
	for camera in ExtensionsApi.general.get_canvas().get_tree().get_nodes_in_group("CanvasCameras"):
		camera.fit_to_frame(Vector2(new_width, new_height))
	waiting_for_resize_confirmation = false
	generate()

func _on_resize_canceled() -> void :
	waiting_for_resize_confirmation = false

func _get_max_frame_count() -> int:
	var ref_img = find_child("ReferenceImagePreview", true)
	if ref_img == null or ref_img.reference_image == null or ref_img.reference_image.is_invisible():
		return MAX_FRAMES
	var w: int = ref_img.reference_image.get_width()
	var h: int = ref_img.reference_image.get_height()
	if w > 256 or h > 256:
		return MIN_FRAMES
	var area: int = w * h
	if area <= 0:
		return MAX_FRAMES
	var raw: int = min(MAX_FRAMES, TOTAL_PIXEL_BUDGET / area)
	if raw % 2 != 0:
		raw -= 1
	return max(MIN_FRAMES, raw)

func _update_frame_count_slider() -> void :
	var slider = find_child("FrameCountSlider")
	if slider == null:
		return
	var max_frames = _get_max_frame_count()
	slider.max_value = max_frames
	if slider.value > max_frames:
		slider.value = max_frames

	var label = find_child("FrameCount")
	if label:
		label.text = "Frame count (%d)" % int(slider.value)

func _get_selected_frame_count() -> int:
	var slider = find_child("FrameCountSlider")
	if slider == null:
		return 4
	return int(slider.value)

func get_payload():
	if enhance_ws.is_active():
		enhance_ws.cancel()
		var button = find_child("EnhanceActionButton")
		button.disabled = false

	var payload: Dictionary = {}


	var reference_image = find_child("ReferenceImagePreview").reference_image
	if reference_image == null:
		ExtensionsApi.dialog.show_error("You need to set a first frame image using the 'Set' button.")
		return null
	elif reference_image.is_invisible():
		ExtensionsApi.dialog.show_error("The first frame image is fully transparent, please set another one.")
		return null

	var width = reference_image.get_width()
	var height = reference_image.get_height()


	var action_text = find_child("ActionInput").text
	if action_text.strip_edges() == "":
		ExtensionsApi.dialog.show_error("Please enter an action description.")
		return null




	if not waiting_for_resize_confirmation and width <= 256 and height <= 256:
		var project_size: Vector2i = ExtensionsApi.project.current_project.size
		if project_size.x != width or project_size.y != height:
			waiting_for_resize_confirmation = true
			_show_resize_confirmation_dialog_(project_size.x, project_size.y, width, height)
			return null


	payload["first_frame"] = {
		"type": "rgba_bytes", 
		"base64": get_image.image_to_base64(reference_image), 
		"width": width, 
		"height": height, 
	}

	payload["action"] = action_text
	payload["frame_count"] = _get_selected_frame_count()


	var seed_text = find_child("SeedInput").text
	payload["seed"] = int(seed_text) if seed_text != "" else 0


	payload["no_background"] = find_child("NoBackgroundCheckbox").button_pressed


	payload["output_method"] = find_child("OutputMethodSelect").text
	payload["output_format"] = "frames"

	payload["model_name"] = "wan"

	return payload

func get_tool_data():
	var reference_image = find_child("ReferenceImagePreview").reference_image
	var width = 64
	var height = 64
	if reference_image != null and not reference_image.is_invisible():
		width = reference_image.get_width()
		height = reference_image.get_height()

	var frame_count = _get_selected_frame_count()
	var output_method = find_child("OutputMethodSelect").text.to_lower()
	var tool_data = {
		"image_amount": frame_count + 1, 
		"cels": {}, 
		"output_method": output_method, 
		"tool_name": "Animate with Text (New)", 
		"url": "animate-with-text-v3", 
		"image_size": {
			"width": width, 
			"height": height
		}, 
		"documentation": "https://www.pixellab.ai/docs/tools/animate-with-text-v3", 
		"tool": self, 
		"tier_requirement": 0, 
		"main_ui_button_name": "AnimateWithTextV3Button"
	}
	return tool_data

func validate_payload(payload):
	var reference_image = find_child("ReferenceImagePreview").reference_image
	if reference_image == null:
		ExtensionsApi.dialog.show_error("You need to set a first frame image using the 'Set' button.")
		return false
	elif reference_image.is_invisible():
		ExtensionsApi.dialog.show_error("The first frame image is fully transparent, please set another one.")
		return false

	var width = reference_image.get_width()
	var height = reference_image.get_height()
	if width > 256 or height > 256:
		ExtensionsApi.dialog.show_error("First frame is too large (%dx%d). Maximum size for animation is 256x256 pixels." % [width, height])
		return false

	var frame_count = _get_selected_frame_count()
	var max_frames = _get_max_frame_count()
	if frame_count > max_frames:
		ExtensionsApi.dialog.show_error("Frame count %d is too high for a %dx%d image. Max frames: %d." % [frame_count, width, height, max_frames])
		return false

	return true

func _preview_image(node_name: String) -> Image:
	var preview = find_child(node_name, true)
	if preview == null or preview.reference_image == null or preview.reference_image.is_invisible():
		return null
	return preview.reference_image

func _get_selected_frame_count() -> int:
	return int(find_child("FrameCountSlider").value)


func _default_slider_value() -> int:
