func _frame_count() -> int:
	return int(find_child("Generate").find_child("FrameCountSlider").value)





static func pose_frame_indices(current_frame: int, count: int) -> Array:
	var frames: = []
	for i in range(count):
		frames.append(current_frame + POSE_FRAME_OFFSET + i)
	return frames


func _pose_frames() -> Array:
	return pose_frame_indices(ExtensionsApi.project.current_project.current_frame, _frame_count())





func _pose_frame_states() -> Array:
	var project = ExtensionsApi.project.current_project
	var states: = []
	for frame in _pose_frames():
		var state: = POSE_READY
		if frame >= len(project.frames):
			state = POSE_NO_FRAME
		elif not SkeletonV3Keypoints.is_complete(DrawSkeleton.get_skeleton_from_frame(frame)):
			state = POSE_NO_SKELETON
		states.append({"frame": frame, "state": state})
	return states

