	var limit_color_option = find_child("LimitColorsSelect").selected
	if limit_color_option == 0:
		payload["color_image"] = {"base64": ""}
	elif limit_color_option == 1:
		payload["color_image"] = get_image.get_limit_color(current_project.current_frame, get_node_or_null("/root/Palettes"), "palette")
	elif limit_color_option == 2:
		payload["color_image"] = get_image.get_limit_color(current_project.current_frame, get_node_or_null("/root/Palettes"), "image")
	elif limit_color_option == 3:
		payload["color_image"] = get_image.get_limit_color(find_child("ReferenceImagePreview").reference_image, get_node_or_null("/root/Palettes"), "reference")
	payload["image_size"] = {}
	payload["image_size"]["width"] = image_select.width
	payload["image_size"]["height"] = image_select.height

	payload["n_frames"] = find_child("NFramesSlider").value
	payload["start_frame_index"] = find_child("StartFrameSlider").value

	payload["image_amount"] = 4
	payload["model_name"] = "generate_movement"
	payload["seed"] = int(find_child("SeedInput").text)
	payload["output_method"] = find_child("OutputMethodSelect").text
	return payload

